<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';admin_required();
$user=admin_user();$errors=[];$stmt=db()->prepare('SELECT * FROM admins WHERE id=?');$stmt->execute([(int)$user['id']]);$admin=$stmt->fetch();if(!$admin)throw new RuntimeException('حساب مدیر پیدا نشد.');
if(isset($_GET['setup'])&&!(int)$admin['two_factor_enabled'])$_SESSION['_admin_2fa_setup_secret']=base32_encode_secret(random_bytes(20));
if(is_post()){
    verify_csrf();$action=scalar_string($_POST['action']??'settings');
    try{
        if($action==='settings'){
            if(!admin_can('manage_admins'))throw new RuntimeException('اجازه تغییر سیاست امنیتی پنل را ندارید.');
            $session=max(15,min(1440,scalar_int($_POST['admin_session_timeout_minutes']??120,120)));$attempts=max(3,min(20,scalar_int($_POST['admin_login_max_attempts']??5,5)));$lock=max(5,min(120,scalar_int($_POST['admin_login_lock_minutes']??15,15)));$retention=max(30,min(1095,scalar_int($_POST['admin_audit_retention_days']??365,365)));$save=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach(['admin_session_timeout_minutes'=>$session,'admin_login_max_attempts'=>$attempts,'admin_login_lock_minutes'=>$lock,'admin_audit_retention_days'=>$retention] as $key=>$value)$save->execute([$key,(string)$value]);admin_audit_event('security_settings_saved');flash('success','تنظیمات امنیت مدیران ذخیره شد.');redirect(app_url('admin/security.php'));
        }
        $password=scalar_string($_POST['current_password']??'');if(!password_verify($password,(string)$admin['password_hash']))throw new RuntimeException('رمز فعلی صحیح نیست.');
        if($action==='enable_2fa'){$secret=(string)($_SESSION['_admin_2fa_setup_secret']??'');$code=scalar_string($_POST['code']??'');if($secret===''||!admin_totp_verify($secret,$code))throw new RuntimeException('کد برنامه احراز هویت معتبر نیست.');$pdo=db();$pdo->beginTransaction();$pdo->prepare('UPDATE admins SET two_factor_secret_enc=?,two_factor_enabled=1 WHERE id=?')->execute([protect_secret($secret),(int)$admin['id']]);$codes=admin_generate_recovery_codes((int)$admin['id']);$pdo->commit();unset($_SESSION['_admin_2fa_setup_secret']);$_SESSION['_new_recovery_codes']=$codes;admin_audit_event('two_factor_enabled','admin',(int)$admin['id']);redirect(app_url('admin/security.php?codes=1'));}
        if($action==='disable_2fa'){$pdo=db();$pdo->beginTransaction();$pdo->prepare('UPDATE admins SET two_factor_secret_enc=NULL,two_factor_enabled=0 WHERE id=?')->execute([(int)$admin['id']]);$pdo->prepare('DELETE FROM admin_recovery_codes WHERE admin_id=?')->execute([(int)$admin['id']]);$pdo->commit();admin_audit_event('two_factor_disabled','admin',(int)$admin['id']);flash('success','احراز هویت دومرحله‌ای غیرفعال شد.');redirect(app_url('admin/security.php'));}
        if($action==='recovery_codes'){if(!(int)$admin['two_factor_enabled'])throw new RuntimeException('ابتدا احراز هویت دومرحله‌ای را فعال کنید.');$_SESSION['_new_recovery_codes']=admin_generate_recovery_codes((int)$admin['id']);admin_audit_event('recovery_codes_regenerated','admin',(int)$admin['id']);redirect(app_url('admin/security.php?codes=1'));}
    }catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getMessage();}
}
$setupSecret=(string)($_SESSION['_admin_2fa_setup_secret']??'');$recoveryCodes=is_array($_SESSION['_new_recovery_codes']??null)?$_SESSION['_new_recovery_codes']:[];unset($_SESSION['_new_recovery_codes']);$issuer=rawurlencode((string)setting('store_name','فروشگاه گلریزان'));$label=rawurlencode((string)setting('store_name','فروشگاه گلریزان').':'.$admin['username']);$otpUrl=$setupSecret!==''?'otpauth://totp/'.$label.'?secret='.$setupSecret.'&issuer='.$issuer.'&digits=6&period=30':'';$adminPage='security';$adminTitle='امنیت مدیران';require __DIR__.'/partials/header.php';
?>
<div class="admin-title"><div><h1>امنیت مدیران</h1><p class="muted">حساب فعلی: <?=e($admin['full_name'])?></p></div><?php if(admin_can('manage_admins')||admin_can('view_audit')):?><div class="admin-actions"><?php if(admin_can('manage_admins')):?><a class="btn btn-secondary" href="<?=e(app_url('admin/admin-users.php'))?>">مدیران</a><?php endif?><?php if(admin_can('view_audit')):?><a class="btn btn-secondary" href="<?=e(app_url('admin/activity-logs.php'))?>">گزارش فعالیت</a><?php endif?></div><?php endif?></div>
<?php foreach($errors as $error):?><div class="flash error"><?=e($error)?></div><?php endforeach?>
<?php if($recoveryCodes):?><div class="card"><h2>کدهای بازیابی جدید</h2><div class="flash error">این کدها فقط همین یک‌بار نمایش داده می‌شوند. آن‌ها را در محل امن نگه دارید.</div><div class="codebox" dir="ltr"><?=e(implode("\n",$recoveryCodes))?></div></div><?php endif?>
<div class="card"><h2>احراز هویت دومرحله‌ای</h2><?php if((int)$admin['two_factor_enabled']):?><div class="flash success">ورود دومرحله‌ای برای حساب شما فعال است.</div><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="recovery_codes"><input type="password" name="current_password" placeholder="رمز فعلی" required><button class="btn btn-secondary">ساخت کدهای بازیابی جدید</button></form><form method="post" class="inline-form" data-confirm="احراز هویت دومرحله‌ای غیرفعال شود؟" style="margin-top:12px"><?=csrf_field()?><input type="hidden" name="action" value="disable_2fa"><input type="password" name="current_password" placeholder="رمز فعلی" required><button class="btn btn-danger">غیرفعال‌کردن 2FA</button></form><?php elseif($setupSecret!==''):?><p>در برنامه Google Authenticator، Microsoft Authenticator یا برنامه مشابه، کلید زیر را دستی وارد کنید:</p><div class="codebox" dir="ltr"><?=e($setupSecret)?></div><details><summary>نشانی فنی برای برنامه احراز هویت</summary><div class="codebox" dir="ltr"><?=e($otpUrl)?></div></details><form method="post" style="margin-top:18px"><?=csrf_field()?><input type="hidden" name="action" value="enable_2fa"><div class="form-grid"><div class="field"><label>رمز فعلی</label><input type="password" name="current_password" required></div><div class="field"><label>کد ۶ رقمی برنامه</label><input name="code" dir="ltr" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></div></div><button class="btn btn-primary">فعال‌سازی</button></form><?php else:?><p>پس از فعال‌سازی، ورود مدیر علاوه بر رمز عبور به کد یک‌بارمصرف برنامه احراز هویت نیاز دارد.</p><a class="btn btn-primary" href="<?=e(app_url('admin/security.php?setup=1'))?>">شروع فعال‌سازی</a><?php endif?></div>
<?php if(admin_can('manage_admins')):?><form method="post" class="card" style="margin-top:20px"><?=csrf_field()?><input type="hidden" name="action" value="settings"><h2>سیاست امنیتی پنل</h2><div class="form-grid"><div class="field"><label>انقضای نشست، دقیقه</label><input type="number" name="admin_session_timeout_minutes" min="15" max="1440" value="<?=e(setting('admin_session_timeout_minutes','120'))?>"></div><div class="field"><label>حداکثر تلاش ورود</label><input type="number" name="admin_login_max_attempts" min="3" max="20" value="<?=e(setting('admin_login_max_attempts','5'))?>"></div><div class="field"><label>مدت قفل ورود، دقیقه</label><input type="number" name="admin_login_lock_minutes" min="5" max="120" value="<?=e(setting('admin_login_lock_minutes','15'))?>"></div><div class="field"><label>نگهداری گزارش فعالیت، روز</label><input type="number" name="admin_audit_retention_days" min="30" max="1095" value="<?=e(setting('admin_audit_retention_days','365'))?>"></div></div><button class="btn btn-primary">ذخیره سیاست امنیتی</button></form><?php endif?>
